import logging
from logging.handlers import MemoryHandler
DEBUG, INFO, WARNING, ERROR, CRITICAL = (logging.DEBUG, logging.INFO, logging.WARNING, logging.ERROR, logging.CRITICAL)

def rec(label, level):
    return logging.LogRecord(label, level, "example.py", 1, label, (), None)

def labels(records):
    return [r.name for r in records]

class Sink(logging.Handler):
    def __init__(self):
        super().__init__()
        self.received = []
        self.flushes = 0
        self.closes = 0

    def emit(self, r):
        self.received.append(r)

    def flush(self):
        self.flushes += 1

    def close(self):
        self.closes += 1
        super().close()

def snapshot(h, t):
    return {"buffer": labels(h.buffer), "delivered": labels(t.received)}

def outcome(f):
    try:
        f()
        return "ok"
    except Exception as exc:
        return type(exc).__name__

